<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';
$admin=require_permission($pdo,'roles.manage');$pageTitle='Rollen & Berechtigungen';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();try{$action=post_string('action');if(!in_array($action,['grant','revoke'],true))throw new InvalidArgumentException('Ungültige Aktion.');governance_role_change($pdo,(int)$admin['id'],(int)post_string('user_id'),post_string('role'),$action==='grant');redirect('/admin/roles.php?saved=1');}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
$users=$pdo->query('SELECT id,username,is_admin,is_active,mfa_secret IS NOT NULL AS has_mfa FROM users ORDER BY id DESC LIMIT 100')->fetchAll();
$grants=$pdo->query('SELECT g.user_id,g.role_code,u.username FROM market_role_grants g JOIN users u ON u.id=g.user_id ORDER BY u.username,g.role_code LIMIT 500')->fetchAll();
include __DIR__.'/../includes/header.php';?>
<main class="container admin-page"><div class="page-heading"><p class="eyebrow">Least privilege</p><h1>Die passende Rolle.</h1><p>Personalrollen benötigen bereits eingerichtete Zwei-Faktor-Authentifizierung. Jede Änderung widerruft bestehende Sitzungen.</p></div><div class="admin-layout"><?php include __DIR__.'/../includes/admin-nav.php';?><div class="admin-content">
<?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?><?php if(isset($_GET['saved'])):?><p class="notice success">Rollenentscheidung gespeichert.</p><?php endif;?>
<section class="panel"><h2>Rolle zuordnen oder entziehen</h2><form method="post" class="form-grid"><?=csrf_field()?><label class="field">Benutzer-ID<input name="user_id" inputmode="numeric" pattern="[0-9]+" required></label><label class="field">Rolle<select name="role"><?php foreach(governance_roles() as $code=>$role):?><option value="<?=h($code)?>"><?=h($role['label'])?></option><?php endforeach;?></select></label><label class="field">Aktion<select name="action"><option value="grant">Zuordnen</option><option value="revoke">Entziehen</option></select></label><button class="button" type="submit">Berechtigung ändern</button></form><p>Initiale Administrationskonten und das eigene Konto werden hier nicht verändert. MFA-Einrichtung für Personal erfolgt kontrolliert über den lokalen CLI-Assistenten.</p></section>
<section class="panel"><h2>Rollen und Rechte</h2><?php foreach(governance_roles() as $role):?><details><summary><?=h($role['label'])?></summary><p><?=h(implode(', ',$role['permissions']))?></p></details><?php endforeach;?></section>
<section class="panel"><h2>Aktuelle Zuordnungen</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Konto</th><th>Rolle</th></tr></thead><tbody><?php foreach($grants as $grant):?><tr><td><?=h($grant['username'])?> #<?=(int)$grant['user_id']?></td><td><?=h(governance_roles()[$grant['role_code']]['label']??$grant['role_code'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Zuletzt angelegte Konten</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Name</th><th>MFA</th><th>Status</th></tr></thead><tbody><?php foreach($users as $row):?><tr><td><?=(int)$row['id']?></td><td><?=h($row['username'])?></td><td><?=$row['has_mfa']?'Eingerichtet':'Fehlt'?></td><td><?=$row['is_active']?'Aktiv':'Deaktiviert'?></td></tr><?php endforeach;?></tbody></table></div></section></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
